  { id: 2, name: 'Mouse', category: 'Electronics', price: 25, stock: 50 },
  { id: 3, name: 'Desk', category: 'Furniture', price: 200, stock: 5 },
  { id: 4, name: 'Chair', category: 'Furniture', price: 150, stock: 8 },
  { id: 5, name: 'Monitor', category: 'Electronics', price: 300, stock: 15 }
];

// Create paginate function here
function paginate(data, page, limit) {
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  return data.slice(startIndex, endIndex);
}

// Create filterData function here
function filterData(data, filters) {
  return data.filter(item => {
    return Object.keys(filters).every(key => {
      if (key === 'category') {
        return item[key].toLowerCase().includes(filters[key].toLowerCase());
      }
      if (key === 'minPrice') {
        return item.price >= filters[key];
      }
      if (key === 'maxPrice') {
        return item.price <= filters[key];
      }
      return true;
    });
  });
}

// Create sortData function here
function sortData(data, sortBy, order = 'asc') {
  return [...data].sort((a, b) => {
    let aVal = a[sortBy];
    let bVal = b[sortBy];

    if (typeof aVal === 'string') {
      aVal = aVal.toLowerCase();
      bVal = bVal.toLowerCase();
    }

    if (order === 'asc') {
      return aVal > bVal ? 1 : -1;
    } else {
      return aVal < bVal ? 1 : -1;
    }
  });
}

// Create processData function here
function processData(data, options) {
  let result = [...data];

  if (options.filters) {
    result = filterData(result, options.filters);
  }

  if (options.sortBy) {
    result = sortData(result, options.sortBy, options.order);
  }

  if (options.page && options.limit) {
    result = paginate(result, options.page, options.limit);
  }

  return result;
}

